export function readPullRequestDiff(repo: string, number: number): PullRequestDiffRead {
  const what = `gh api repos/${repo}/pulls/${number} (diff)`;
  const result = ghRead(
    "api",
    `repos/${repo}/pulls/${number}`,
    "-H",
    "Accept: application/vnd.github.v3.diff",
  );
