    expect(r.body).toContain("already merged");
    expect(r.body).toContain("Continue on #441, the issue this pull request delivered.");
    // And not the one they cannot: no run can be started on a merged pull request, and a
    // resumed one would review a target that is already on the default branch.
    expect(r.body).not.toContain("Resume it");
