/**
 * Where an interrupted run's report sends a person (#455).
 *
 * A reviewer was stopped on a pull request that had already merged. Its report said
 * "Resume it, or say what to do instead" — advice nobody could follow: the review target
 * was on the default branch, GitHub cannot reopen a merged pull request, and no run can be
 * started on one. The person holding the merged work was being pointed back at the dead
 * thread.
 *
 * So the continuation is decided by what became of the THREAD, not by how the run ended:
 * the same wrong appears on a merge-derived stop and on a failure that happens to land on a
 * merged pull request. It is asserted at the level a person sees it — the comment body the
 * script posts — because every link in the chain (the read, the branch, the sentence) has to
 * hold for any of this to be true.
 */
describe("post_result_comment.ts on an interrupted run", () => {
  /** The REST object, as `gh api repos/.../pulls/N` returns it. */
  const pullRequest = (fields: { state: "open" | "closed"; mergedAt?: string | null; body?: string }) =>
    JSON.stringify({ state: fields.state, merged_at: fields.mergedAt ?? null, body: fields.body ?? "" });

  /**
   * Run the script for a stopped run on `number`, against a fake `gh` that answers the pull
   * request read with `pr`.
   */
  function run(args: { number: string; pr: string }) {
    const dir = mkdtempSync(join(tmpdir(), "atomaton-post-result-"));
    writeFileSync(join(dir, "atomaton_output.txt"), "Reviewed two files, then this arrived.");
    try {
      const r = runWithFakeGh(
        scriptPath("post_result_comment.ts"),
        [
          "--number", args.number, "--type", "pr", "--agent", "reviewer",
          "--notify", "octocat", "--ended-because", "stopped",
          "--run-url", "http://example.com/run/1", "--output", join(dir, "atomaton_output.txt"),
        ],
        {
          cwd: dir,
          env: { GITHUB_REPOSITORY: "owner/repo" },
          rules: [
            // The pull request read first: its rule is the more specific one, and the POST
            // below would otherwise be answered as a read.
            { match: ["api", `repos/owner/repo/pulls/${args.number}`], stdout: args.pr },
            { match: ["api", "comments"], stdout: "42" },
          ],
        },
      );
      const body = r.ghCalls.find((c) => c.includes("--method"))?.join(" ") ?? "";
      return { ...r, body };
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  }

  test("a merged pull request says the work is in, and points at the issue it delivered", () => {
    const r = run({
      number: "455",
      pr: pullRequest({ state: "closed", mergedAt: "2026-11-06T14:27:05Z", body: "<!-- atomaton:parent-issue=441 -->" }),
    });
    expect(r.status).toBe(0);
    // The sentence a person could act on: where the follow-up work actually belongs.
    expect(r.body).toContain("is merged already");
    expect(r.body).toContain("Continue on #441, the issue this pull request delivered.");
    // And not the one they cannot follow. Both places that offer a resume are checked,
    // because a footer saying "comment /resume to continue" underneath the sentence above
    // would contradict it in the same comment.
    expect(r.body).not.toContain("Resume it");
    expect(r.body).not.toContain("/resume");
  });

  test("a merged pull request with no recorded parent still says there is nothing here", () => {
    const r = run({ number: "455", pr: pullRequest({ state: "closed", mergedAt: "2026-11-06T14:27:05Z" }) });
    expect(r.status).toBe(0);
    expect(r.body).toContain("is merged already");
    // No `#N` invented: a guessed number sends somebody to an unrelated thread.
    expect(r.body).not.toContain("Continue on #");
  });

  test("an open pull request keeps the resume sentence it always had", () => {
    const r = run({ number: "455", pr: pullRequest({ state: "open" }) });
    expect(r.status).toBe(0);
    expect(r.body).toContain("Resume it, or say what to do instead.");
    expect(r.body).toContain("/resume");
    expect(r.body).not.toContain("is merged already");
  });

  /**
   * A pull request closed without merging is not a dead end: GitHub reopens it, so the
   * advice names the undo. Saying "resume it" is the wrong half — `/resume` on a closed node
   * starts nothing — and saying "already merged" would be false.
   */
  test("a pull request closed without merging is reopened, not resumed", () => {
    const r = run({ number: "455", pr: pullRequest({ state: "closed" }) });
    expect(r.status).toBe(0);
    expect(r.body).toContain("reopen it");
    expect(r.body).not.toContain("Resume it");
    expect(r.body).not.toContain("is merged already");
  });

  /**
   * A read that did not happen is not evidence that the thread is closed. The resume
   * sentence is what a person can act on once it is read, and it is the wording this
   * comment had before any of this existed.
   */
  test("an unreadable pull request keeps the resume sentence rather than guessing", () => {
    const dir = mkdtempSync(join(tmpdir(), "atomaton-post-result-"));
    writeFileSync(join(dir, "atomaton_output.txt"), "Reviewed two files, then this arrived.");
    try {
      const r = runWithFakeGh(
        scriptPath("post_result_comment.ts"),
        [
          "--number", "455", "--type", "pr", "--agent", "reviewer", "--notify", "octocat",
          "--ended-because", "stopped", "--run-url", "http://example.com/run/1",
          "--output", join(dir, "atomaton_output.txt"),
        ],
        {
          cwd: dir,
          env: { GITHUB_REPOSITORY: "owner/repo" },
          rules: [
            { match: ["api", "pulls/455"], code: 1, stdout: "" },
            { match: ["api", "comments"], stdout: "42" },
          ],
        },
      );
      expect(r.status).toBe(0);
      expect(r.ghCalls.find((c) => c.includes("--method"))?.join(" ") ?? "").toContain(
        "Resume it, or say what to do instead.",
      );
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });

  /**
   * The read is only worth paying for when the sentence can change. A run that finished says
   * what it did, which no thread state alters — so for a pull request that finished normally
   * this is one fewer `gh` call on every review.
   */
  test("a run that completed reads nothing about the thread", () => {
    const dir = mkdtempSync(join(tmpdir(), "atomaton-post-result-"));
    writeFileSync(join(dir, "atomaton_output.txt"), "Reviewed and reported.");
    try {
      const r = runWithFakeGh(
        scriptPath("post_result_comment.ts"),
        [
          "--number", "455", "--type", "pr", "--agent", "reviewer", "--notify", "octocat",
          "--ended-because", "completed", "--run-url", "http://example.com/run/1",
          "--output", join(dir, "atomaton_output.txt"),
        ],
        { cwd: dir, env: { GITHUB_REPOSITORY: "owner/repo" }, rules: [{ match: ["api", "comments"], stdout: "42" }] },
      );
      expect(r.status).toBe(0);
      expect(r.ghCalls.some((c) => c.join(" ").includes("pulls/455"))).toBe(false);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});
